import{_ as n,o as h,c as i,a4 as c}from"./chunks/framework.CRKgIIuH.js";const s=JSON.parse('{"title":"QA pháp lý — đối chiếu nguồn chính thống","description":"","frontmatter":{},"headers":[],"relativePath":"course/book/appendices/legal-verification.md","filePath":"course/book/appendices/legal-verification.md"}'),a={name:"course/book/appendices/legal-verification.md"};function d(e,t,r,g,u,o){return h(),i("div",null,[...t[0]||(t[0]=[c('<h1 id="qa-phap-ly-—-đoi-chieu-nguon-chinh-thong" tabindex="-1">QA pháp lý — đối chiếu nguồn chính thống <a class="header-anchor" href="#qa-phap-ly-—-đoi-chieu-nguon-chinh-thong" aria-label="Permalink to &quot;QA pháp lý — đối chiếu nguồn chính thống&quot;">​</a></h1><p><strong>Ngày tra cứu:</strong> 21/11/2026<br><strong>Phạm vi:</strong> các mục tham khảo [54], [55], [57]–[58], [60], [62]–[66], [79]–[82] trong <code>docs/literature-review/index.md</code>.<br><strong>Nguyên tắc:</strong> chỉ ghi chi tiết đọc được hoặc được xác nhận từ nguồn chính thống; không sửa thân bài trong đợt QA này.</p><h2 id="bang-đoi-chieu" tabindex="-1">Bảng đối chiếu <a class="header-anchor" href="#bang-đoi-chieu" aria-label="Permalink to &quot;Bảng đối chiếu&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Mục</th><th>Số hiệu/văn bản</th><th>Ngày ban hành</th><th>Ngày hiệu lực</th><th>URL nguồn chính thống</th><th>Ngày tra cứu</th><th>Trạng thái</th><th>Chi tiết đã đối chiếu</th></tr></thead><tbody><tr><td style="text-align:right;">[54]</td><td>Regulation (EU) No 536/2014</td><td>16/04/2014</td><td>16/06/2014 theo Điều 99</td><td><a href="https://eur-lex.europa.eu/eli/reg/2014/536/oj" target="_blank" rel="noreferrer">EUR-Lex</a></td><td>21/11/2026</td><td>XÁC NHẬN</td><td>Điều 58: hồ sơ master file của thử nghiệm được lưu ít nhất 25 năm sau khi kết thúc; hồ sơ y tế người tham gia theo luật quốc gia.</td></tr><tr><td style="text-align:right;">[55]</td><td>Thông tư 33/2025/TT-BYT</td><td>01/07/2025</td><td>01/07/2025</td><td><a href="https://vbpl.vn/FileData/TW/Lists/vbpq/Attachments/181190/VanBanGoc_663505.pdf" target="_blank" rel="noreferrer">VBPL — bản PDF gốc</a></td><td>21/11/2026</td><td>XÁC NHẬN</td><td>Văn bản và Điều 2 xác nhận ngày ban hành, hiệu lực và thay thế Thông tư 53/2017/TT-BYT. Các mức 30 năm/20 năm trong review phải tiếp tục đối chiếu trực tiếp từng dòng phụ lục trước khi coi là xác nhận đầy đủ.</td></tr><tr><td style="text-align:right;">[57]</td><td>Regulation (EU) 2016/679 (GDPR)</td><td>27/04/2016</td><td>25/05/2018</td><td><a href="https://eur-lex.europa.eu/eli/reg/2016/679/oj" target="_blank" rel="noreferrer">EUR-Lex</a></td><td>21/11/2026</td><td>XÁC NHẬN</td><td>Điều 9, Điều 4(5), Điều 89 và Recital 26 là các điểm nguồn chính thống liên quan dữ liệu sức khỏe, giả danh hóa và nghiên cứu; ngày áp dụng được ghi trên EUR-Lex.</td></tr><tr><td style="text-align:right;">[58]</td><td>Regulation (EU) 2025/327 (EHDS)</td><td>11/02/2025</td><td>26/03/2025</td><td><a href="https://eur-lex.europa.eu/eli/reg/2025/327/oj" target="_blank" rel="noreferrer">EUR-Lex</a></td><td>21/11/2026</td><td>XÁC NHẬN</td><td>Xác nhận số hiệu, ngày ban hành, ngày công bố 05/03/2025 và hiệu lực theo văn bản; các mốc áp dụng theo chương cần đối chiếu điều khoản cụ thể nếu dùng để sửa câu trong review.</td></tr><tr><td style="text-align:right;">[60]</td><td>45 CFR §164.514</td><td>Quy định liên bang Hoa Kỳ; ngày ban hành gốc cần tra theo lịch sử CFR</td><td>Văn bản hiện hành trên eCFR</td><td><a href="https://www.ecfr.gov/current/title-45/section-164.514" target="_blank" rel="noreferrer">eCFR</a></td><td>21/11/2026</td><td>XÁC NHẬN</td><td>Xác nhận hai phương pháp khử định danh: Expert Determination và Safe Harbor; nội dung định danh phải loại bỏ và phải có căn cứ rủi ro tái định danh rất nhỏ.</td></tr><tr><td style="text-align:right;">[62]</td><td>Luật Bảo vệ dữ liệu cá nhân 91/2025/QH15</td><td>26/06/2025</td><td>01/01/2026</td><td><a href="https://sav.gov.vn/vi/page/tongkiemtoan/bai-viet/tai-lieu-gioi-thieu-luat-bao-ve-du-lieu-ca-nhan" target="_blank" rel="noreferrer">Kiểm toán Nhà nước — tài liệu giới thiệu chính thức</a></td><td>21/11/2026</td><td>XÁC NHẬN</td><td>Nguồn chính thức xác nhận Luật gồm 05 chương, 39 điều và phạm vi bảo vệ dữ liệu cá nhân. Chưa coi riêng chi tiết về Cục A05 và toàn bộ hồ sơ đánh giá tác động là đã xác nhận từ trang giới thiệu này.</td></tr><tr><td style="text-align:right;">[63]</td><td>Nghị định 356/2025/NĐ-CP</td><td>31/12/2025</td><td>01/01/2026</td><td><a href="https://vbpl.moj.gov.vn/bocongan/Pages/vbpq-thuoctinh.aspx?ItemID=187276" target="_blank" rel="noreferrer">CSDL quốc gia về VBPL — Bộ Công an</a></td><td>21/11/2026</td><td>XÁC NHẬN</td><td>Xác nhận số hiệu, ngày ban hành, ngày hiệu lực, tình trạng còn hiệu lực và việc quy định chi tiết Luật Bảo vệ dữ liệu cá nhân. Review đúng khi dùng Nghị định 356 làm khung từ 01/01/2026.</td></tr><tr><td style="text-align:right;">[64]</td><td>Luật Dữ liệu 60/2024/QH15</td><td>Chưa xác nhận được</td><td>Chưa xác nhận được</td><td>—</td><td>21/11/2026</td><td>KHÔNG TÌM ĐƯỢC NGUỒN CHÍNH THỐNG</td><td>Chỉ tìm thấy các văn bản nhà nước dẫn chiếu số hiệu; chưa tìm được bản toàn văn chính thống trong lượt tra cứu này. Không xác nhận thêm nội dung trong review.</td></tr><tr><td style="text-align:right;">[65]</td><td>Thông tư 13/2025/TT-BYT</td><td>06/06/2025</td><td>21/07/2025</td><td><a href="https://xaydungchinhsach.chinhphu.vn/lo-trinh-trien-khai-ho-so-benh-an-dien-tu-tai-cac-benh-vien-119250610163849953.htm" target="_blank" rel="noreferrer">Cổng TTĐT Chính phủ — lộ trình hồ sơ bệnh án điện tử</a></td><td>21/11/2026</td><td>XÁC NHẬN</td><td>Nguồn Chính phủ xác nhận hạn 30/09/2025 cho bệnh viện và 31/12/2026 cho cơ sở khám chữa bệnh khác; đồng thời xác nhận ngày ban hành và hiệu lực 21/07/2025.</td></tr><tr><td style="text-align:right;">[66]</td><td>Thông tư 50/2025/TT-BYT</td><td>31/12/2025</td><td>27/02/2026</td><td><a href="https://www.impe-qn.org.vn/van-ban-cua-bo-y-te/cmb/33" target="_blank" rel="noreferrer">Trang văn bản của đơn vị thuộc Bộ Y tế</a></td><td>21/11/2026</td><td>XÁC NHẬN MỘT PHẦN (không có toàn văn chính thức)</td><td>Trang cơ quan thuộc Bộ Y tế xác nhận văn bản tồn tại; ngày hiệu lực 27/02/2026 được đối chiếu ở bản toàn văn được lập chỉ mục, nhưng chưa tìm được URL toàn văn chính thức của Bộ trong lượt tra cứu.</td></tr><tr><td style="text-align:right;">[79]</td><td>Nghị quyết 57-NQ/TW</td><td>22/12/2024</td><td>Không nêu ngày hiệu lực riêng</td><td><a href="https://xaydungchinhsach.chinhphu.vn/toan-van-nghi-quyet-ve-dot-pha-phat-trien-khoa-hoc-cong-nghe-doi-moi-sang-tao-va-chuyen-doi-so-quoc-gia-119241224180048642.htm" target="_blank" rel="noreferrer">Cổng TTĐT Chính phủ — toàn văn</a></td><td>21/11/2026</td><td>XÁC NHẬN</td><td>Xác nhận số hiệu, ngày ban hành và chủ đề đột phá khoa học, công nghệ, đổi mới sáng tạo và chuyển đổi số quốc gia.</td></tr><tr><td style="text-align:right;">[80]</td><td>Nghị quyết 72-NQ/TW</td><td>09/09/2025</td><td>Không nêu ngày hiệu lực riêng</td><td><a href="https://ubkttw.vn/tai-lieu-tu-lieu/bo-chinh-tri/nghi-quyet-so-72-nq-tw-ngay-09-9-2025-cua-bo-chinh-tri-ve-mot-so-giai-phap-dot-pha-tang-cuong-bao-ve-cham-soc-va-nang-ca.html" target="_blank" rel="noreferrer">Ủy ban Kiểm tra Trung ương — toàn văn/tài liệu</a></td><td>21/11/2026</td><td>XÁC NHẬN</td><td>Xác nhận số hiệu, ngày và tiêu đề. Nguồn Chính phủ mô tả mục tiêu tiếp cận y tế công bằng, chăm sóc sức khỏe toàn dân; không suy rộng thành các chỉ tiêu khác nếu chưa đọc toàn văn tương ứng.</td></tr><tr><td style="text-align:right;">[81]</td><td>Quyết định 1308/QĐ-TTg</td><td>18/07/2026</td><td>18/07/2026</td><td><a href="https://vanban.chinhphu.vn/?docid=218908&amp;pageid=27160" target="_blank" rel="noreferrer">Cổng TTĐT Chính phủ</a></td><td>21/11/2026</td><td>XÁC NHẬN</td><td>Xác nhận số hiệu, ngày ban hành, ngày hiệu lực và trích yếu Chiến lược dữ liệu quốc gia giai đoạn 2026–2030, tầm nhìn 2045.</td></tr><tr><td style="text-align:right;">[82]</td><td>Quyết định 3218/QĐ-BYT</td><td>14/10/2026</td><td>Chưa xác nhận được</td><td><a href="https://dongthap.gov.vn/web/syt/chi-tiet?id=11607181" target="_blank" rel="noreferrer">Cổng thông tin tỉnh Đồng Tháp — thông báo triển khai</a></td><td>21/11/2026</td><td>KHÔNG TÌM ĐƯỢC NGUỒN CHÍNH THỐNG</td><td>Tìm thấy thông báo của cơ quan nhà nước về triển khai quyết định, nhưng chưa tìm được bản quyết định/toàn văn chính thức trên cổng Bộ Y tế; không xác nhận nội dung quy chế hay ngày hiệu lực.</td></tr></tbody></table><h2 id="cac-điem-khac-biet-hoac-chua-đu-bang-chung" tabindex="-1">Các điểm KHÁC BIỆT hoặc chưa đủ bằng chứng <a class="header-anchor" href="#cac-điem-khac-biet-hoac-chua-đu-bang-chung" aria-label="Permalink to &quot;Các điểm KHÁC BIỆT hoặc chưa đủ bằng chứng&quot;">​</a></h2><ul><li>[55] Review nêu cụ thể các mức 30 năm và 20 năm; nguồn PDF chính thống đã xác nhận văn bản/hiệu lực nhưng lượt tra cứu này chưa trích được đúng dòng phụ lục tương ứng. Đây là điểm cần đọc lại, không được tự coi là đã xác nhận.</li><li>[62] Review nêu Cục A05 và hồ sơ đánh giá tác động; trang giới thiệu chính thức đã xác nhận 05 chương/39 điều nhưng chưa đủ để xác nhận từng chi tiết thủ tục đó.</li><li>[64] Chưa có bản toàn văn chính thống trong lượt tra cứu; không xác nhận các diễn giải nội dung.</li><li>[66] Ngày hiệu lực 27/02/2026 khớp bản văn được lập chỉ mục và thông tin ngành, nhưng thiếu URL toàn văn chính thức của Bộ trong lượt tra cứu.</li><li>[82] Chưa có bản nguồn chính thức của quyết định; chỉ có thông báo triển khai của cơ quan nhà nước.</li></ul><h2 id="gioi-han-tra-cuu" tabindex="-1">Giới hạn tra cứu <a class="header-anchor" href="#gioi-han-tra-cuu" aria-label="Permalink to &quot;Giới hạn tra cứu&quot;">​</a></h2><p>Tra cứu được thực hiện ngày 21/11/2026 bằng tìm kiếm web và mở các trang công báo/cổng cơ quan nhà nước, EUR-Lex và eCFR. Một số cổng không lập chỉ mục toàn văn hoặc trả bản PDF/phụ lục khó tìm kiếm; vì vậy “XÁC NHẬN” chỉ áp dụng cho chi tiết ghi trong cột đối chiếu, không phải xác nhận toàn bộ mọi mệnh đề trong review. Nguồn thương mại chỉ được dùng như gợi ý khi đối chiếu, không làm nguồn chính trong bảng.</p><h2 id="kiem-tra-lai-đoc-lap-21-11-2026" tabindex="-1">Kiểm tra lại độc lập (21/11/2026) <a class="header-anchor" href="#kiem-tra-lai-đoc-lap-21-11-2026" aria-label="Permalink to &quot;Kiểm tra lại độc lập (21/11/2026)&quot;">​</a></h2><p>Sau khi hoàn tất bảng trên, hai chi tiết được tải lại và đối chiếu trực tiếp trên nguồn: [62] trang của Kiểm toán Nhà nước ghi &quot;Luật số 91/2025/QH15 gồm 05 Chương, 39 Điều&quot;; [65] bài của Cổng TTĐT Chính phủ ghi theo khoản 2 Điều 4 Thông tư 13/2025/TT-BYT, bệnh viện chậm nhất 30/9/2025, cơ sở khám chữa bệnh khác chậm nhất 31/12/2026. Cả hai khớp với thân bài. Các mục còn lại chưa được kiểm tra lại độc lập.</p>',10)])])}const b=n(a,[["render",d]]);export{s as __pageData,b as default};
